use super::*;use crate::sim::Simulator;
struct Fixed(u8);impl sha3::digest::XofReader for Fixed{fn read(&mut self,out:&mut[u8]){out.fill(self.0);}}
fn gate(k:K,a:u64,b:u64,t:u64)->Op{let mut o=Op::empty();o.kind=k;o.q_control1=QubitId(a);o.q_control2=QubitId(b);o.q_target=QubitId(t);o}
fn fixture()->Vec<Op>{let mut v=vec![];for q in 0..2{let mut o=gate(K::AppendToRegister,NO,NO,q);o.r_target.0=0;v.push(o);}v.push(gate(K::X,NO,NO,2));v.push(gate(K::CCX,0,1,2));let mut h=gate(K::Hmr,NO,NO,2);h.c_target.0=0;v.push(h);v.push(gate(K::CCX,1,0,2));v.push(gate(K::R,NO,NO,4));v}
#[test]fn copy_cache_one_arbitrary_first_target_preserves_all_wires_phase_and_measurements(){let v=fixture();let out=rewrite(v.clone(),3,5,3);assert_eq!(out.iter().filter(|o|o.kind==K::CCX).count(),1);assert_eq!(v.iter().filter(|o|matches!(o.kind,K::R|K::Hmr)).collect::<Vec<_>>(),out.iter().filter(|o|matches!(o.kind,K::R|K::Hmr)).collect::<Vec<_>>());for pattern in [0,255,0xa5,0x5a]{for input in 0..4{let(mut ra,mut rb)=(Fixed(pattern),Fixed(pattern));let mut a=Simulator::new(5,1,&mut ra);let mut b=Simulator::new(5,1,&mut rb);a.qubits[0]=input&1;a.qubits[1]=input>>1&1;a.phase=0xa55a;b.qubits.clone_from(&a.qubits);b.phase=a.phase;a.apply_iter(v.iter());b.apply_iter(out.iter());assert_eq!(a.qubits,b.qubits);assert_eq!(a.bits,b.bits);assert_eq!(a.phase,b.phase);}}}
#[test]fn copy_cache_one_storage_phase_touch_is_rejected(){let mut v=fixture();v.insert(4,gate(K::Z,NO,NO,3));assert!(std::panic::catch_unwind(||rewrite(v,3,6,3)).is_err());}
#[test]fn copy_cache_one_abi_storage_is_rejected(){let mut v=fixture();let mut r=gate(K::AppendToRegister,NO,NO,3);r.r_target.0=0;v.push(r);assert!(std::panic::catch_unwind(||rewrite(v,3,5,3)).is_err());}
#[test]fn copy_cache_one_explicit_condition_and_scope_are_rejected(){let mut v=fixture();v[5].c_condition.0=0;assert!(std::panic::catch_unwind(||rewrite(v,3,5,3)).is_err());let mut v=fixture();let mut push=Op::empty();push.kind=K::PushCondition;push.c_condition.0=0;let mut pop=Op::empty();pop.kind=K::PopCondition;v.insert(3,push);v.insert(7,pop);assert!(std::panic::catch_unwind(||rewrite(v,4,6,3)).is_err());}
#[test]fn copy_cache_one_production_binding_refuses_another_input(){assert!(std::panic::catch_unwind(||run(vec![])).is_err());}
